$('modulePage').addEventListener('click',async e=>{const deactivateAddon=e.target.closest('[data-addon-deactivate]');if(deactivateAddon){if(!await showConfirm('این افزودنی غیرفعال شود؟ سفارش‌های قبلی بدون تغییر می‌مانند.'))return;try{await apiRequest('/api/product-addons/'+encodeURIComponent(deactivateAddon.dataset.addonDeactivate),{method:'DELETE'});await renderProductsPage()}catch(error){alert(error.message)}return}const exportLedger=e.target.closest('[data-supplier-ledger-export]');if(exportLedger){const panel=$('supplierLedgerPanel');let statement;try{statement=JSON.parse(panel?.dataset.supplierLedger||'null')}catch(error){statement=null}if(!statement){alert('اطلاعات گردش حساب برای خروجی در دسترس نیست.');return}const quote=value=>{const text=String(value??'');const safe=/^[\s]*[=+@-]/.test(text)?"'"+text:text;return '"'+safe.replace(/"/g,'""')+'"'};const rows=[['نوع سند','شماره فاکتور','تاریخ','بدهکار / پرداخت','بستانکار / خرید','مانده'],...(statement.items||[]).map(item=>[item.sourceType==='invoice'?'فاکتور خرید':'پرداخت به تأمین‌کننده',item.reference,item.entryDate||new Date(Number(item.createdAt)*1000).toISOString(),item.debit,item.credit,item.balanceAfter])];const csv='\uFEFF'+rows.map(row=>row.map(quote).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='mg-supplier-ledger-'+String(statement.supplier?.name||'supplier').replace(/[^\p{L}\p{N}-]+/gu,'-')+'.csv';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(e.target.closest('[data-supplier-ledger-close]')){$('supplierLedgerPanel').innerHTML='';return}if(e.target.id==='addPurchaseLine'){const root=$('purchaseLines');const first=root?.querySelector('.purchase-line');if(!root||!first)return;const row=first.cloneNode(true);row.querySelector('[name="quantity"]').value='1';row.querySelector('[name="unitCost"]').value='';row.querySelector('[name="productId"]').selectedIndex=0;const remove=document.createElement('button');remove.type='button';remove.className='secondary remove-purchase-line';remove.textContent='حذف قلم';row.appendChild(remove);root.appendChild(row)}else if(e.target.classList.contains('remove-purchase-line')){const rows=$('purchaseLines')?.querySelectorAll('.purchase-line');if(rows?.length>1)e.target.closest('.purchase-line').remove()}else if(e.target.closest('[data-reservation-cancel]')){const button=e.target.closest('[data-reservation-cancel]');const id=button.dataset.reservationCancel;apiRequest('/api/gamenet/reservations/'+encodeURIComponent(id)+'/cancel',{method:'POST',body:JSON.stringify({})}).then(()=>renderGameNetPage()).catch(error=>alert(error.message))}});
