$('addTransaction').onclick=openModal;$('dismiss').onclick=closeModal;$('cancel').onclick=closeModal;$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal()});$('search').addEventListener('input',renderTransactions);$('transactions').addEventListener('click',async e=>{const b=e.target.closest('[data-delete]');if(!b)return;const index=transactions.findIndex(t=>String(t.id)===b.dataset.delete);if(index<0)return;if(!await showConfirm('این تراکنش برگشت زده شود؟'))return;if(apiMode){try{await apiRequest('/api/transactions/'+encodeURIComponent(b.dataset.delete),{method:'DELETE'})}catch(error){alert(error.message);return}}const removed=transactions.splice(index,1)[0];if(persist()){renderStats();renderTransactions()}else transactions.splice(index,0,removed)});$('exportData').addEventListener('click',async()=>{try{const payload=apiMode?await apiRequest('/api/backup'):{schema:'mg-business-backup',version:1,exportedAt:new Date().toISOString(),transactions};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='mg-business-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error){alert(error.message)}});
$('importData').addEventListener('click',()=>$('importFile').click());
$('importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>50*1024*1024)throw new Error('حجم فایل پشتیبان نباید بیشتر از ۵۰ مگابایت باشد.');const parsed=JSON.parse(await file.text());if(apiMode){if(parsed.schema!=='mg-business-server-backup')throw new Error('در حالت سرور فقط نسخه پشتیبان کامل سرور قابل بازیابی است.');if(!await showConfirm('تمام اطلاعات عملیاتی این فضای کاری با نسخه پشتیبان جایگزین می‌شود. کاربران و رمزهای ورود فعلی حفظ می‌شوند. ادامه می‌دهید؟'))return;const restored=await apiRequest('/api/backup/restore',{method:'POST',body:JSON.stringify(parsed)});const data=moduleAccess?.has('accounting')?await apiRequest('/api/transactions'):{items:[]};transactions=data.items.map(t=>Core.validateTransaction(t)).filter(r=>r.ok).map(r=>r.value);persist();renderStats();renderTransactions();if(current==='overview')renderDailyBestSelling();else navigate(current);alert('بازیابی کامل شد. تعداد رکوردهای بازیابی‌شده: '+fa(restored.restoredRows));return}const checked=Core.validateBackup(parsed);if(!checked.ok)throw new Error(checked.error);if(!await showConfirm('با بازیابی این فایل، تمام تراکنش‌های فعلی با اطلاعات فایل جایگزین می‌شوند. ادامه می‌دهید؟'))return;const previous=transactions;transactions=checked.value;if(persist()){renderStats();renderTransactions();alert('بازیابی اطلاعات با موفقیت انجام شد.')}else transactions=previous}catch(error){alert('بازیابی انجام نشد: '+error.message)}finally{e.target.value=''}});
$('transactionForm').addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.currentTarget),amount=Number(data.get('amount')),title=String(data.get('title')||'').trim();if(!title||!Number.isSafeInteger(amount)||amount<=0){alert('عنوان و مبلغ معتبر وارد کنید. مبلغ باید عدد صحیح و مثبت باشد.');return}const transactionForm=e.currentTarget,kind=String(data.get('kind')),category=String(data.get('category'));const signature=JSON.stringify([title,amount,kind,category]);if(transactionForm.dataset.requestSignature!==signature){transactionForm.dataset.requestId=stableRequestId(transactionForm,signature);transactionForm.dataset.requestTimestamp=new Date().toISOString()}const candidate={id:transactionForm.dataset.requestId,title,amount,kind,category,createdAt:transactionForm.dataset.requestTimestamp};const checked=Core.validateTransaction(candidate);if(!checked.ok){alert(checked.error);return}const item=checked.value;if(apiMode){try{await apiRequest('/api/transactions',{method:'POST',body:JSON.stringify(item)})}catch(error){alert(error.message);return}}transactions.unshift(item);if(persist()){renderStats();renderTransactions();if(current==='accounting')renderAccountingPage();delete transactionForm.dataset.requestId;delete transactionForm.dataset.requestSignature;delete transactionForm.dataset.requestTimestamp;closeModal()}else transactions.shift()});
